// Package aiprices is the AI gateway's built-in model price catalog
// (ADR-994). catalog.json is generated by scripts/gen_ai_price_catalog.py
// from LiteLLM's MIT-licensed price data (see NOTICE) and holds list prices
// in US-dollar millicents (ADR 20261019123822): per million tokens or
// characters, per image, per
// audio minute (ADR-997), per second of video (ADR-1432), and per web
// search, file search and GB container session (ADR-1433), with separate
// audio token prices (ADR 20261019072722). An integration's own price list
// always wins; the catalog prices the models it does not name.
package aiprices

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"sync"

	"github.com/onebox-faas/faas/pkg/api"
)

//go:embed catalog.json
var catalogJSON []byte

// Price is one model's price. Token prices are millicents per million
// tokens. The media prices (ADR-997) are nil when the catalog has none:
// image-token prices per million tokens, Image per image, AudioMinute per
// minute of input audio and Characters per million input characters.
// VideoSecond prices each second of generated video (ADR-1432); a
// "<model>@<resolution>" row prices one resolution apart. WebSearch,
// FileSearch and CodeSessionGB price built-in tool uses (ADR-1433).
// InputAudio, CachedInputAudio and OutputAudio price audio tokens per
// million (ADR 20261019072722).
type Price struct {
	Input, CachedInput, CacheWrite, Output                               int64
	InputImage, OutputImage, Image, AudioMinute, Characters, VideoSecond *int64
	WebSearch, FileSearch, CodeSessionGB                                 *int64
	InputAudio, CachedInputAudio, OutputAudio                            *int64
}

// catalogFields is the column order of a catalog row.
const catalogFields = "input,cached_input,cache_write,output,input_image,output_image,image,audio_minute,characters,video_second," +
	"web_search,file_search,code_session_gb,input_audio,cached_input_audio,output_audio"

// catalogWidth is the number of columns in a catalog row.
const catalogWidth = 16

// Entry is one catalog model and its price.
type Entry struct {
	Model string
	Price Price
}

// Catalog is a parsed price catalog. Currency is always the billing
// currency (ADR 20261019123822).
type Catalog struct {
	Source    string
	Generated string
	Currency  string
	providers map[string]map[string]Price
}

type catalogFile struct {
	Source    string                                     `json:"source"`
	Generated string                                     `json:"generated"`
	Currency  string                                     `json:"currency"`
	Fields    []string                                   `json:"fields"`
	Providers map[string]map[string][catalogWidth]*int64 `json:"providers"`
}

// Parse validates a catalog file.
func Parse(data []byte) (*Catalog, error) {
	var file catalogFile
	if err := json.Unmarshal(data, &file); err != nil {
		return nil, fmt.Errorf("parse AI price catalog: %w", err)
	}
	if strings.Join(file.Fields, ",") != catalogFields || file.Source == "" ||
		file.Generated == "" || file.Currency != api.BillingCurrency {
		return nil, fmt.Errorf("parse AI price catalog: header is incomplete or not in %s", api.BillingCurrency)
	}
	catalog := &Catalog{Source: file.Source, Generated: file.Generated, Currency: file.Currency,
		providers: make(map[string]map[string]Price, len(file.Providers))}
	for provider, models := range file.Providers {
		if provider == "" || !api.ValidOutboundAIProvider(provider) {
			return nil, fmt.Errorf("parse AI price catalog: unknown provider %q", provider)
		}
		prices := make(map[string]Price, len(models))
		for model, row := range models {
			if model == "" || len(model) > api.OutboundAIModelNameMaxBytes || strings.TrimSpace(model) != model {
				return nil, fmt.Errorf("parse AI price catalog: %s model %q is invalid", provider, model)
			}
			if !validRow(row) {
				return nil, fmt.Errorf("parse AI price catalog: %s model %q has an invalid price", provider, model)
			}
			prices[model] = Price{Input: *row[0], CachedInput: *row[1], CacheWrite: *row[2], Output: *row[3],
				InputImage: row[4], OutputImage: row[5], Image: row[6], AudioMinute: row[7], Characters: row[8],
				VideoSecond: row[9], WebSearch: row[10], FileSearch: row[11], CodeSessionGB: row[12],
				InputAudio: row[13], CachedInputAudio: row[14], OutputAudio: row[15]}
		}
		catalog.providers[provider] = prices
	}
	return catalog, nil
}

// validRow requires the four token prices and bounds every price present.
func validRow(row [catalogWidth]*int64) bool {
	for index, value := range row {
		maximum := api.MaxOutboundAIPriceMillicentsPerMTok
		switch index {
		case 6:
			maximum = api.MaxOutboundAIPriceMillicentsPerImage
		case 7:
			maximum = api.MaxOutboundAIPriceMillicentsPerAudioMinute
		case 9:
			maximum = api.MaxOutboundAIPriceMillicentsPerVideoSecond
		case 10, 11, 12:
			maximum = api.MaxOutboundAIPriceMillicentsPerToolUse
		}
		if (value == nil && index < 4) || (value != nil && (*value < 0 || *value > maximum)) {
			return false
		}
	}
	return true
}

var defaultCatalog = sync.OnceValue(func() *Catalog {
	catalog, err := Parse(catalogJSON)
	if err != nil {
		// catalog.json is generated and covered by tests; a broken embed
		// is a build defect, not a runtime condition.
		panic(err)
	}
	return catalog
})

// Default is the embedded catalog.
func Default() *Catalog { return defaultCatalog() }

// Models lists one provider's catalog in model order.
func (c *Catalog) Models(provider string) []Entry {
	prices := c.providers[provider]
	out := make([]Entry, 0, len(prices))
	for model, price := range prices {
		out = append(out, Entry{Model: model, Price: price})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Model < out[j].Model })
	return out
}

// bedrockRegionPrefixes are cross-region inference profile prefixes.
var bedrockRegionPrefixes = []string{"us.", "eu.", "apac.", "global.", "jp.", "au.", "ca.", "us-gov."}

// Lookup finds the catalog entry for a provider-reported or path model. It
// tries the exact name, then the name without a "models/" path prefix, a
// Bedrock ARN path or cross-region prefix, then the longest catalog model
// the name extends at a '-', '@' or ':' boundary, so a dated or versioned
// snapshot ("gpt-4o-2024-08-06", "claude-sonnet-4-5@20250929") prices as its
// family when the catalog lacks the exact snapshot.
func (c *Catalog) Lookup(provider, model string) (Entry, bool) {
	prices := c.providers[provider]
	if len(prices) == 0 || model == "" {
		return Entry{}, false
	}
	candidates := []string{model}
	trimmed := strings.TrimPrefix(model, "models/")
	if strings.HasPrefix(trimmed, "arn:") {
		trimmed = trimmed[strings.LastIndexByte(trimmed, '/')+1:]
	}
	if trimmed != model {
		candidates = append(candidates, trimmed)
	}
	if provider == api.OutboundAIProviderBedrock {
		for _, prefix := range bedrockRegionPrefixes {
			if rest, ok := strings.CutPrefix(trimmed, prefix); ok {
				candidates = append(candidates, rest)
			}
		}
	}
	for _, candidate := range candidates {
		if price, ok := prices[candidate]; ok {
			return Entry{Model: candidate, Price: price}, true
		}
	}
	for _, candidate := range candidates {
		for i := len(candidate) - 1; i > 0; i-- {
			if boundary := candidate[i]; boundary != '-' && boundary != '@' && boundary != ':' {
				continue
			}
			if price, ok := prices[candidate[:i]]; ok {
				return Entry{Model: candidate[:i], Price: price}, true
			}
		}
	}
	return Entry{}, false
}
